// The only place to configure the indexer.
const VAULT_PATH = '';                       // TODO: absolute path to the vault folder
const SUPABASE_URL = '';                     // TODO: https://<project>.supabase.co
const EMBEDDING_MODEL = 'text-embedding-3-small';   // 1536 dimensions, matches schema.sql

if (!VAULT_PATH) throw new Error('VAULT_PATH is not configured in "Config"');
if (!SUPABASE_URL) throw new Error('SUPABASE_URL is not configured in "Config"');

const base = SUPABASE_URL.replace(/\/+$/, '');
return [{
  json: {
    vaultPath: VAULT_PATH.replace(/[\\/]+$/, ''),
    // Only markdown. Attachments are deliberately out of scope.
    glob: VAULT_PATH.replace(/[\\/]+$/, '') + '/**/*.md',
    embeddingModel: EMBEDDING_MODEL,
    embeddingsUrl: 'https://api.openai.com/v1/embeddings',
    chunksUrl: base + '/rest/v1/vault_chunks',
    tombstoneUrl: base + '/rest/v1/vault_chunks?deleted_at=is.null',
  },
}];

// Splits notes into chunks along headings.
//
// The chunk id is path + heading + a hash of the content, so an edit produces a new id
// and an untouched note produces exactly the ids it produced last night. That is what
// lets workflow 02 answer "has this chunk changed" without a second store of its own.
const MIN = 800;
const MAX = 1200;
const OVERLAP = 100;

const cfg = $('Config').first().json;

// Small, stable, dependency-free. Only used to detect change, never for security.
const hash = (s) => {
  let h1 = 0x811c9dc5, h2 = 0x01000193;
  for (let i = 0; i < s.length; i++) {
    h1 = Math.imul(h1 ^ s.charCodeAt(i), 16777619) >>> 0;
    h2 = Math.imul(h2 + s.charCodeAt(i) + i, 2246822519) >>> 0;
  }
  return (h1.toString(16) + h2.toString(16)).padStart(16, '0');
};

const relative = (p) => String(p).replace(/\\/g, '/').replace(cfg.vaultPath.replace(/\\/g, '/') + '/', '');

const chunks = [];
const paths = new Set();

for (const item of $input.all()) {
  const json = item.json || {};
  const rawPath = json.filePath || json.path || json.fileName || '';
  const body = String(json.data || json.text || json.content || '');
  if (!rawPath || !body.trim()) continue;

  const path = relative(rawPath);
  paths.add(path);

  // Split on markdown headings, keeping the heading with its section.
  const lines = body.replace(/\r/g, '').split('\n');
  const sections = [];
  let current = { heading: '', lines: [] };
  for (const line of lines) {
    const m = /^(#{1,6})\s+(.*)$/.exec(line);
    if (m) {
      if (current.lines.length || current.heading) sections.push(current);
      current = { heading: m[2].trim(), lines: [] };
    } else {
      current.lines.push(line);
    }
  }
  if (current.lines.length || current.heading) sections.push(current);

  for (const section of sections) {
    const text = section.lines.join('\n').trim();
    if (!text) continue;

    // A long section is cut into MAX-sized pieces with OVERLAP characters carried over,
    // so a sentence spanning a cut is still retrievable from one of the two pieces.
    const pieces = [];
    if (text.length <= MAX) {
      pieces.push(text);
    } else {
      let start = 0;
      while (start < text.length) {
        const end = Math.min(start + MAX, text.length);
        pieces.push(text.slice(start, end));
        if (end === text.length) break;
        start = end - OVERLAP;
      }
    }

    for (const piece of pieces) {
      // A piece shorter than MIN is kept only when it is the whole section: dropping it
      // would lose short notes entirely.
      if (piece.length < MIN && pieces.length > 1) continue;
      const content = piece.trim();
      if (!content) continue;
      chunks.push({
        id: path + '#' + section.heading + '#' + hash(content),
        path,
        heading: section.heading || null,
        content,
      });
    }
  }
}

return [{
  json: {
    source: 'vault',
    key_field: 'id',
    items: chunks,
    chunkCount: chunks.length,
    paths: [...paths],
    embeddingModel: cfg.embeddingModel,
    embeddingsUrl: cfg.embeddingsUrl,
    chunksUrl: cfg.chunksUrl,
    tombstoneUrl: cfg.tombstoneUrl,
  },
}];

// One embeddings request per batch of new chunks. Unchanged chunks never get here,
// which is the entire point of running deduplication first.
const dedup = $input.first().json || {};
const state = $('Chunk notes').first().json;
const items = Array.isArray(dedup.new_items) ? dedup.new_items : [];

// The embeddings API takes an array, so a nightly run is one call, not one per chunk.
return [{
  json: {
    ...state,
    newChunks: items,
    newCount: items.length,
    body: {
      model: state.embeddingModel,
      input: items.map((c) => c.content),
    },
  },
}];

// Pairs embeddings back to their chunks by position, which is the order the API
// preserves, and builds the rows plus the tombstone filter.
const res = $input.first().json || {};
const state = $('Build embedding request').first().json;

const vectors = Array.isArray(res.data) ? res.data : [];
if (vectors.length && vectors.length !== state.newChunks.length) {
  throw new Error('embedding count ' + vectors.length + ' does not match chunk count '
    + state.newChunks.length + '; refusing to store misaligned vectors');
}

const now = new Date().toISOString();
const rows = state.newChunks.map((c, i) => ({
  id: c.id,
  path: c.path,
  heading: c.heading,
  content: c.content,
  embedding: vectors[i] ? vectors[i].embedding : null,
  updated_at: now,
  deleted_at: null,
})).filter((r) => Array.isArray(r.embedding));

// Notes that no longer exist in the vault are tombstoned, never deleted: a note removed
// by accident should be recoverable, and history is cheap.
const livePaths = state.paths;
const tombstoneFilter = livePaths.length
  ? '&path=not.in.(' + livePaths.map((p) => '"' + p.replace(/"/g, '') + '"').join(',') + ')'
  : '';

return [{
  json: {
    rows,
    stored: rows.length,
    skipped: state.newChunks.length - rows.length,
    chunkCount: state.chunkCount,
    pathCount: livePaths.length,
    chunksUrl: state.chunksUrl,
    tombstoneUrl: state.tombstoneUrl + tombstoneFilter,
    tombstonePatch: { deleted_at: now },
    canTombstone: livePaths.length > 0,
  },
}];
